export const NHIS_SPECIALTY_BY_KEY: ReadonlyMap<string, NhisSpecialty> = new Map(
  NHIS_SPECIALTIES.map(item => [item.key, item]),
)

/** The keys that are on until an operator changes the list. */
export const DEFAULT_CONSULT_SPECIALTY_KEYS: readonly string[] = Object.freeze(
  NHIS_SPECIALTIES.filter(item => item.clinical && item.role === "Лекари").map(item => item.key),
)

export function specialtyLabel(key: string, language: string): string | null {
  const item = NHIS_SPECIALTY_BY_KEY.get(key)
  return item ? (language === "bg" ? item.labelBg : item.labelEn) : null
}
